const item = $input.first().json;
let content = item.output || item.text || item.response || JSON.stringify(item);

// Get the extracted text from the previous Extract Text node
const extractedText = $('Extract Text').first().json.text || '';

if (typeof content === 'object' && content.classification) {
  content.extracted_text = extractedText;
  return [{ json: content }];
}

if (typeof content === 'string') {
  content = content.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
  const match = content.match(/\{[\s\S]*\}/);
  if (match) content = match[0];
}

try {
  const parsed = JSON.parse(content);
  if (!parsed.classification) throw new Error('Missing classification');

  // Ensure classification has all required fields
  parsed.classification = parsed.classification || {};
  parsed.classification.contract_type = parsed.classification.contract_type || 'other';
  parsed.classification.partner_type = parsed.classification.partner_type || 'other';
  parsed.classification.complexity = parsed.classification.complexity || 'moderate';
  parsed.classification.revenue_model = parsed.classification.revenue_model || ['other'];
  parsed.classification.confidence = parsed.classification.confidence || 0.5;

  // Ensure other required fields
  parsed.contract_info = parsed.contract_info || { partner_name: 'Unknown' };
  parsed.summary = parsed.summary || 'No summary available';
  parsed.processing_recommendation = parsed.processing_recommendation || { should_process: true, reason: 'Unknown', estimated_rules: 0 };

  // Add the extracted text to the response
  parsed.extracted_text = extractedText;

  return [{ json: parsed }];
} catch (e) {
  return [{ json: { 
    error: true, 
    message: e.message,
    classification: {
      contract_type: 'other',
      partner_type: 'other',
      complexity: 'unknown',
      revenue_model: ['other'],
      confidence: 0
    },
    summary: 'Error processing contract',
    extracted_text: extractedText
  } }];
}

const item = $input.first().json;

// Grab filename from webhook binary data before it gets dropped
let pdfName = 'unknown.pdf';
try {
  const webhookBin = $('Webhook - Classify').first().binary || {};
  pdfName = webhookBin.data?.fileName || 
            webhookBin.data0?.fileName || 
            item.pdf_name || 
            item.file_name || 
            'unknown.pdf';
} catch(e) {
  pdfName = item.pdf_name || item.file_name || 'unknown.pdf';
}

const timestamp = new Date().toISOString();
const classification_id = `${pdfName}::${timestamp}`;
const pdf_id = classification_id;

const out = {
  ...item,
  timestamp_utc: timestamp,
  pdf_name: pdfName,
  pdf_id,
  classification_id,
  model: 'gpt-5.1',
  prompt_version: 'classify_v1'
};

return [{ json: out }];

const item = $input.first().json;
let content = item.output || item.text || item.response || JSON.stringify(item);

if (typeof content === 'object' && content.rules) {
  return [{ json: content }];
}

if (typeof content === 'string') {
  content = content.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
  const match = content.match(/\{[\s\S]*\}/);
  if (match) content = match[0];
}

try {
  const parsed = JSON.parse(content);
  if (!parsed.rules) throw new Error('Missing rules');

  // Ensure all rules have the required fields
  parsed.rules = parsed.rules.map((r, i) => ({
    rule_number: r.rule_number || i + 1,
    rule_text: r.rule_text || '',
    confidence: r.confidence || 0.5,
    source: r.source || 'Unknown',
    category: r.category || 'other',
    approved: false,
    is_calculable: r.is_calculable !== undefined ? r.is_calculable : true,
    calculation_type: r.calculation_type || 'unknown',
    extracted_values: r.extracted_values || {
      percentages: [],
      amounts: [],
      thresholds: [],
      operators: []
    }
  }));

  // Ensure other required fields exist
  parsed.glossary = parsed.glossary || {};
  parsed.extraction_stats = parsed.extraction_stats || {
    total_rules_found: parsed.rules.length,
    calculable_rules: parsed.rules.length,
    skipped_rules: 0,
    skipped_reasons: []
  };

  return [{ json: parsed }];
} catch (e) {
  return [{ json: { 
    error: true, 
    message: e.message, 
    rules: [] 
  } }];
}

const item = $input.first().json;

// Grab pdf_name from the original extract webhook request body
let pdfName = 'unknown.pdf';
try {
  const webhookBody = $('Webhook - Extract Rules').first().json.body || {};
  pdfName = webhookBody.pdf_name || 'unknown.pdf';
} catch(e) {
  pdfName = 'unknown.pdf';
}

// Grab classification_id the same way
let classificationId = '';
try {
  const webhookBody = $('Webhook - Extract Rules').first().json.body || {};
  classificationId = webhookBody.classification_id || '';
} catch(e) {
  classificationId = '';
}

const timestamp = new Date().toISOString();
const execution_id = `${pdfName}::${timestamp}`;
const pdf_id = classificationId || execution_id;

const out = {
  ...item,
  timestamp_utc: timestamp,
  pdf_name: pdfName,
  pdf_id,
  classification_id: classificationId,
  execution_id,
  model: 'gpt-5.1',
  prompt_version: 'extract_v1'
};

return [{ json: out }];

const run = $input.first().json;
const rules = run.rules || [];
return rules.map((r, idx) => {
  const ruleNum = r.rule_number ?? (idx + 1);
  const ruleId = `${run.execution_id}_r${String(ruleNum).padStart(3,'0')}`;
  return {
    json: {
      execution_id: run.execution_id,
      classification_id: run.classification_id,
      timestamp_utc: run.timestamp_utc,
      pdf_id: run.pdf_id || '',
      pdf_name: run.pdf_name,
      model: run.model,
      prompt_version: run.prompt_version,
      rule_number: ruleNum,
      rule_id: ruleId,
      rule_text: r.rule_text || '',
      category: r.category || '',
      calculation_type: r.calculation_type || '',
      confidence: r.confidence ?? '',
      source: r.source || '',
      is_calculable: r.is_calculable !== undefined ? r.is_calculable : true,
      reviewed: false,
      reviewed_at: ''
    }
  };
});

parameters.text:
=You are a Financial Calculation Builder for AdContractIQ. Build mathematical expression chains from contract rules.

Here is the complete input data:

{{ JSON.stringify($json) }}

INSTRUCTIONS:
1. Look at the 'finalized_rules' array - these are contract rules with revenue share percentages and calculations
2. For each rule (or group of related rules), create a calculation chain showing step-by-step math
3. Use the 'base_revenue' value (or 100 if not provided) for sample calculations
4. Common patterns: "after deducting X% COS" = subtract first, "Y% revenue share" = multiply

OUTPUT FORMAT (PURE JSON ONLY - NO MARKDOWN, NO LATEX):
{
  "calculation_chains": [
    {
      "chain_id": "unique_id",
      "label": "Calculation Name",
      "description": "What this calculates",
      "steps": [
        {
          "step_number": 1,
          "operation": "subtract",
          "label": "Step description",
          "formula": "Variable_Name * 0.20",
          "formula_display": "Gross Revenue * 20%",
          "variables": {"Gross_Revenue": 100, "Rate": 0.20},
          "result": 20.00,
          "running_total": 80.00,
          "display": "$100.00 - $20.00 (20% COS) = $80.00",
          "rule_references": [1]
        }
      ],
      "final_amounts": {"party_1": 48.00, "party_2": 32.00}
    }
  ],
  "summary": {
    "total_chains": 1,
    "rules_used": [1, 2],
    "rules_not_used": [],
    "notes": ""
  }
}

CRITICAL: Return ONLY the JSON object above. No code blocks, no LaTeX (\text, \times), no explanations. Just pure JSON.

