const item = $input.first().json;
let content = item.output || item.text || item.response || JSON.stringify(item);

if (typeof content === 'object' && content.calculation_chains) {
  return [{ json: content }];
}

if (typeof content === 'string') {
  content = content.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
  const match = content.match(/\{[\s\S]*\}/);
  if (match) content = match[0];
}

try {
  const parsed = JSON.parse(content);
  if (!parsed.calculation_chains) throw new Error('Missing calculation_chains');
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { error: true, message: e.message, calculation_chains: [] } }];
}

const inputJson = $input.first().json;
const body = inputJson.body || inputJson;
const rules = body.finalized_rules || [];
const executionId = body.execution_id || body.pdf_id || '';

if (!Array.isArray(rules) || rules.length === 0) {
  return [];
}

const timestamp = new Date().toISOString();

return rules.map((r, idx) => {
  const ruleNum = r.rule_number ?? (idx + 1);
  const ruleId = r.rule_id || (executionId ? `${executionId}_r${String(ruleNum).padStart(3,'0')}` : '');
  return {
    json: {
      rule_id: ruleId,
      reviewed: true,
      reviewed_at: timestamp
    }
  };
});
